17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    /**
121	     * Determines whether an owner already exists using the same telephone number.
122	     * Comparison ignores letter case and surrounding or repeated whitespace.
123	     *
124	     * @param owner the candidate owner to check
125	     * @return {@code true} if any other owner with the same telephone is already stored
126	     */
127	    private boolean ownerAlreadyExists(Owner owner) {
128	        String telephone = normalize(owner.getTelephone());
129	        return this.clinicService.findAllOwners().stream()
130	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
131	    }
132	
133	    /**
134	     * Determines whether another owner already uses the same email address.
135	     * Owners without an email are ignored, so a missing email never conflicts.
136	     * Comparison ignores letter case and surrounding or repeated whitespace.
137	     *
138	     * @param owner the candidate owner to check
139	     * @return {@code true} if the candidate supplies an email already used by a stored owner
140	     */
141	    private boolean emailAlreadyExists(Owner owner) {
142	        String email = normalize(owner.getEmail());
143	        if (email == null || email.isEmpty()) {
144	            return false;
145	        }
146	        return this.clinicService.findAllOwners().stream()
147	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
148	    }
149	
150	    /**
151	     * Normalizes a value for duplicate detection so that comparisons ignore letter
152	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
153	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
154	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
155	     * both normalize to {@code "john smith"}.
156	     *
157	     * @param value the raw value, may be {@code null}
158	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
159	     */
160	    private static String normalize(String value) {
161	        if (value == null) {
162	            return null;
163	        }
164	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	        this.clinicService.saveOwner(currentOwner);
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Transactional
185	    @Override
186	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        this.clinicService.deleteOwner(owner);
192	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Pet pet = petMapper.toPet(petFieldsDto);
204	        owner.setId(ownerId);
205	        pet.setOwner(owner);
206	        pet.getType().setName(null);
207	        this.clinicService.savePet(pet);
208	        PetDto petDto = petMapper.toPetDto(pet);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
210	            .buildAndExpand(pet.getId()).toUri());
211	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
217	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
218	        if (currentOwner != null) {
219	            Pet currentPet = this.clinicService.findPetById(petId);
220	            if (currentPet != null) {
221	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
222	                currentPet.setName(petFieldsDto.getName());
223	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
224	                this.clinicService.savePet(currentPet);
225	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
